// P1–P4. S-AF and Subject Detect Off except P3, which is C-AF through converter
// 0x604050e5. The candidate image is the swapped overlay. The control has no
// AF-ON overlay and uses the same edges. Literals are the predicted records in
// work/out/target-bytes.md. A failed comparison stops the run.
// k5 passed P1 and P2. C-AF stopped because the raw 0x60063380 read of key 289
// stayed 0. Focus is now the session getter s.get(289) and s.get(25), after
// the Fn lever pump and the converter 0x604050e5 group write.
// Do not edit this file after it has run.
// Usage: node26 work/scripts/exp_edges_k6.mjs om-emu
import { writeFileSync, mkdirSync } from 'node:fs';
import { resolve } from 'node:path';
import { pathToFileURL } from 'node:url';
import { runZone } from './zone_session_k1.mjs';

const [checkout] = process.argv.slice(2);
if (!checkout) {
  process.stderr.write('usage: node26 work/scripts/exp_edges_k6.mjs om-emu\n');
  process.exit(2);
}
let API_SET = 0;
async function bindApi() {
  const { A } = await import(pathToFileURL(resolve(checkout, 'emu/src/fw/model.mjs')).href);
  API_SET = A(0x50ac4afe);
}
const GET = 0x60063380;
const CONVERTER = 0x604050e5;
const SETTER = 0x6041937f;
const OUT = resolve('work/out/edges-k6.jsonl');
const lines = [];
const emit = (row) => {
  lines.push(JSON.stringify(row));
  console.log(JSON.stringify(row));
  mkdirSync(resolve('work/out'), { recursive: true });
  writeFileSync(OUT, lines.join('\n') + '\n');
};
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
const EDGES = [
  ['s1', 'down'], ['s1', 'up'],
  ['afon', 'down'], ['afon', 'up'],
  ['s1', 'down'], ['afon', 'down'], ['afon', 'up'], ['s1', 'up'],
  ['afon', 'down'], ['s1', 'down'], ['s1', 'up'], ['afon', 'up'],
];
const OWNERS = [1, 0, 2, 0, 1, 2, 1, 0, 2, 2, 2, 0];
const SINGLE = [0x0e, 0x02, 0x00, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const SMALL = [0x0e, 0x02, 0x03, 0x00, 0x01, 0x00, 0x01, 0x00, 0x00, 0x00];
const STOCK_TARGET = [0x0e, 0x02, 0x02, 0x00, 0x1b, 0x00, 0x27, 0x00, 0x00, 0x00];
const HALF = [0x0e, 0x02, 0x03, 0x00, 0x03, 0x00, 0x03, 0x00, 0x00, 0x00];
const HALF_EDGES = new Set([0, 1, 3, 4, 6, 7, 11]);
const STOCK = {
  k90a1: [1, 1],
  k1dd1: [3, 3, 3, 3, 3, 3, 3, 3, 3, 3],
  k99a1: [2, 0, 2, 0, 2, 0, 5, 5],
  k9a41: 0,
  k5962: [526, 526, 526, 526, 526, 526],
  home: {
    '0x99d2': [526, 526, 526],
    '0x9fa1': [0, 0, 0],
    '0xdfa1': [0],
    '0x1ea1': [0],
    '0x9ec1': [0],
    '0x9ed1': [1],
    '0x9ee1': [0],
    '0x9ef1': [0],
    '0x59b1': [0],
  },
};

function watched(cells) {
  return {
    k90a1: cells.k90a1, k1dd1: cells.k1dd1, k99a1: cells.k99a1,
    k9a41: cells.k9a41, k5962: cells.k5962, home: cells.home,
  };
}
function readSetting(ctx, key, index) {
  return ctx.l.call(ctx.native(GET), { d0: key, d1: index, a0: 0 }, null, null, 200000).d0 & 0xffff;
}
function setPublic(ctx, sid, value) {
  const grouped = sid === 289 || sid === 66 || sid === 67;
  const argument = grouped
    ? (ctx.l.call(ctx.native(CONVERTER), { d0: sid, d1: value }, null, null, 200000).d0 >>> 0)
    : value;
  const ret = ctx.l.call(API_SET, { d0: sid, d1: argument }, null, null, 200000).d0 >>> 0;
  ctx.idle(500);
  return { sid, value, argument, ret };
}
function snap(ctx) {
  const cells = ctx.cells();
  const own = ctx.readOwn();
  return {
    target: ctx.readTarget(),
    owner: own[4],
    status: own[5],
    enabled: own[6],
    held: [own[0], own[1]],
    profile: cells.profile,
    focus: ctx.s.get(289),
    focusActive: ctx.s.get(25),
    subject: readSetting(ctx, 1712, 0),
    cells: watched(cells),
  };
}
async function chooseZone(ctx, rights, value) {
  ctx.press('menu');
  for (let i = 0; i < 20; i++) ctx.press('left');
  ctx.press('down');
  ctx.press('down');
  ctx.press('ok');
  ctx.press('down');
  ctx.press('down');
  ctx.press('ok');
  for (let i = 0; i < rights; i++) ctx.press('right');
  const shot = ctx.shot('zone-' + value);
  ctx.press('ok');
  for (let i = 0; i < 8 && ctx.s.screen() !== 'shooting'; i++) ctx.press('menu');
  const profile = ctx.readByte(ctx.PROFILE);
  ctx.emit('observe', { step: 'zone-set', value, rights, profile, screen: ctx.s.screen(), highlight: shot.highlight, texts: shot.texts });
  if (ctx.s.screen() !== 'shooting') throw new Error('menu did not return to shooting');
  if (profile !== value) throw new Error('profile byte ' + profile + ' after choosing ' + value);
}
function assertEdge(name, index, got, expect) {
  const problems = [];
  if (got.subject !== 0) problems.push('subject');
  if (got.focus !== expect.focus) problems.push('focus');
  if (got.focusActive !== expect.focus) problems.push('focus-active');
  if (!same(got.cells.k90a1, STOCK.k90a1)) problems.push('k90a1');
  if (!same(got.cells.k1dd1, STOCK.k1dd1)) problems.push('k1dd1');
  if (!same(got.cells.k99a1, STOCK.k99a1)) problems.push('k99a1');
  if (got.cells.k9a41 !== STOCK.k9a41) problems.push('k9a41');
  if (!same(got.cells.k5962, STOCK.k5962)) problems.push('k5962');
  const home = { ...got.cells.home };
  const wantHome = { ...STOCK.home };
  if (expect.home9fa1 !== undefined) {
    home['0x9fa1'] = null;
    wantHome['0x9fa1'] = null;
  }
  if (!same(home, wantHome)) problems.push('home');
  if (expect.profile !== undefined && got.profile !== expect.profile) problems.push('profile');
  if (expect.owner !== undefined) {
    if (got.enabled !== 1) problems.push('enabled');
    if (got.owner !== expect.owner) problems.push('owner');
    if (got.status !== 0) problems.push('status');
  }
  if (expect.target && !same(got.target, expect.target)) problems.push('target');
  emit({
    experiment: name, edge: index, key: EDGES[index][0], dir: EDGES[index][1],
    pass: problems.length === 0, problems, got, expect,
  });
  if (problems.length) throw new Error(name + ' edge ' + index + ' ' + problems.join(','));
}

const controlSaf = [];
const controlCaf = [];

async function runEdges(name, { candidate, focus, zone, afonTarget, controlSnaps }) {
  await runZone({
    checkout,
    outPath: 'work/out/session-k6-' + name + '.jsonl',
    tag: 'edge-k6-' + name,
    candidate,
    help: true,
    rowLabel: true,
    overlayCsv: candidate ? 'work/out/overlay-changed-bytes.csv' : null,
    fatalShots: true,
    explanation: candidate
      ? name + ' uses the swapped overlay. Zone type is the RAM byte. Size and position stay on the legacy provider. Role: behaviour.'
      : name + ' is the no-overlay control, same edges.',
    change: candidate ? 'profile source swap' : 'none',
    async drive(ctx) {
      await bindApi();
      const brought = ctx.bringUp();
      ctx.emit('behaviour', { step: 'bring-up', label: 'EMULATOR-ONLY native bring-up. Role: behaviour.', ...brought });
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(500);
      const mode = setPublic(ctx, 289, focus);
      const subject = setPublic(ctx, 1712, 0);
      ctx.emit('observe', { step: 'mode', mode, subject, stored: ctx.s.get(289), active: ctx.s.get(25), readSubject: readSetting(ctx, 1712, 0) });
      if (zone !== null) await chooseZone(ctx, zone.rights, zone.value);
      const stored = focus === 0 ? controlSaf : controlCaf;
      emit({ experiment: name, record: 'before-edges', cells: snap(ctx).cells, profile: ctx.readByte(ctx.PROFILE) });
      if (candidate && (same(afonTarget, HALF) || same(afonTarget, STOCK_TARGET))) {
        throw new Error(name + ' predicted AF-ON target is not distinct');
      }
      for (let i = 0; i < EDGES.length; i++) {
        ctx.key(EDGES[i][0], EDGES[i][1]);
        ctx.idle(600);
        const got = snap(ctx);
        let target;
        if (candidate) target = HALF_EDGES.has(i) ? HALF : afonTarget;
        else if (focus === 0) target = STOCK_TARGET;
        else target = i === 0 ? null : stored[0].target;
        if (!candidate) stored[i] = got;
        assertEdge(name, i, got, {
          focus,
          profile: zone ? zone.value : (candidate ? 0 : undefined),
          owner: candidate ? OWNERS[i] : undefined,
          target,
        });
      }
    },
  }).then((result) => {
    if (!result.ok) throw new Error(name + ' failed: ' + result.failed);
  });
}

async function runP4() {
  emit({
    experiment: 'p4',
    record: 'explanation',
    text: 'The zone type no longer comes from AF Home 0x9fa1. Set the row to Single through the menu and record the AF-ON target. Write 0x9fa1 index 0 to 1. The AF-ON target must stay the Single record. Then call the profile setter with 2. The AF-ON target must become the Small record. Half-press cells stay put. 0x9fa1 is the only AF Home cell this run writes.',
  });
  await runZone({
    checkout,
    outPath: 'work/out/session-k6-p4.jsonl',
    tag: 'edge-k6-p4',
    candidate: true,
    help: true,
    rowLabel: true,
    overlayCsv: 'work/out/overlay-changed-bytes.csv',
    fatalShots: true,
    explanation: 'P4 isolates the profile byte from 0x9fa1. Role: behaviour.',
    change: 'profile source swap, plus one AF Home write used only as the negative control',
    async drive(ctx) {
      await bindApi();
      ctx.bringUp();
      ctx.s.switch_input('lever', 1);
      ctx.s.camapp.pump();
      ctx.idle(500);
      setPublic(ctx, 289, 0);
      setPublic(ctx, 1712, 0);
      await chooseZone(ctx, 1, 1);
      ctx.key('afon', 'down');
      ctx.idle(600);
      const before = snap(ctx);
      emit({ experiment: 'p4', phase: 'before-home-write', got: before });
      if (!same(before.target, SINGLE) || before.owner !== 2) throw new Error('p4 single target');
      const wrote = setPublic(ctx, 0x9fa1, 1);
      ctx.idle(200);
      const afterHome = snap(ctx);
      emit({ experiment: 'p4', phase: 'after-9fa1-write', wrote, got: afterHome });
      if (afterHome.cells.home['0x9fa1'][0] !== 1) throw new Error('p4 0x9fa1 did not change');
      if (!same(afterHome.target, SINGLE)) throw new Error('p4 target followed 0x9fa1');
      ctx.l.call(ctx.native(SETTER), { d0: 0x3d6f, d1: 2 }, null, null, 200000);
      ctx.idle(200);
      const afterByte = snap(ctx);
      emit({ experiment: 'p4', phase: 'after-profile-2', got: afterByte });
      if (afterByte.profile !== 2) throw new Error('p4 profile byte');
      if (!same(afterByte.target, SMALL)) throw new Error('p4 target did not follow the profile byte');
      if (!same(afterByte.cells.k99a1, STOCK.k99a1) || !same(afterByte.cells.k1dd1, STOCK.k1dd1)) {
        throw new Error('p4 half-press cells moved');
      }
      ctx.key('afon', 'up');
      ctx.idle(300);
    },
  }).then((result) => {
    if (!result.ok) throw new Error('p4 failed: ' + result.failed);
  });
}

try {
  await runEdges('control-saf', { candidate: false, focus: 0, zone: null, afonTarget: null, controlSnaps: null });
  await runEdges('p1', { candidate: true, focus: 0, zone: { rights: 1, value: 1 }, afonTarget: SINGLE, controlSnaps: controlSaf });
  await runEdges('p2', { candidate: true, focus: 0, zone: { rights: 2, value: 2 }, afonTarget: SMALL, controlSnaps: controlSaf });
  await runEdges('control-caf', { candidate: false, focus: 1, zone: null, afonTarget: null, controlSnaps: null });
  await runEdges('p3', { candidate: true, focus: 1, zone: { rights: 1, value: 1 }, afonTarget: SINGLE, controlSnaps: controlCaf });
  await runP4();
  emit({ record: 'done', ok: true });
} catch (e) {
  emit({ record: 'done', ok: false, error: String(e && e.stack ? e.stack : e) });
  process.exitCode = 1;
}
